CREATE TABLE public.sponsor_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, provider text NOT NULL DEFAULT 'manual' CHECK(provider IN ('manual','everflow')), currency text NOT NULL DEFAULT 'EUR' CHECK(currency IN ('EUR','USD','GBP')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused')), synced_at timestamptz, last_error text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sponsor_accounts TO authenticated; GRANT ALL ON public.sponsor_accounts TO service_role;
ALTER TABLE public.sponsor_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY sponsor_accounts_read ON public.sponsor_accounts FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND (allowed_paths @> ARRAY['/dashboard/templates'] OR allowed_paths @> ARRAY['/dashboard/finance'] OR allowed_paths @> ARRAY['/dashboard/campaigns'])));
CREATE POLICY sponsor_accounts_write ON public.sponsor_accounts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'superadmin')) WITH CHECK(public.has_role(auth.uid(),'superadmin'));
CREATE TABLE public.sponsor_credentials (account_id uuid PRIMARY KEY REFERENCES public.sponsor_accounts(id) ON DELETE CASCADE, api_key text NOT NULL);
GRANT ALL ON public.sponsor_credentials TO service_role;
ALTER TABLE public.sponsor_credentials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sponsor_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.sponsor_accounts(id), external_id text, name text NOT NULL, category text NOT NULL DEFAULT '', model text NOT NULL DEFAULT 'CPL' CHECK(model IN ('CPA','CPL','CPC','CPM','RevShare')), payout numeric(14,4) NOT NULL DEFAULT 0 CHECK(payout>=0), currency text NOT NULL DEFAULT 'EUR' CHECK(currency IN ('EUR','USD','GBP')), geo text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','capped','missing')), tracking_url text NOT NULL DEFAULT '', subject text NOT NULL DEFAULT '', html text NOT NULL DEFAULT '', rules text NOT NULL DEFAULT '', daily_cap integer CHECK(daily_cap>=0), monthly_cap integer CHECK(monthly_cap>=0), synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,external_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sponsor_offers TO authenticated; GRANT ALL ON public.sponsor_offers TO service_role;
ALTER TABLE public.sponsor_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY sponsor_offers_read ON public.sponsor_offers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND (allowed_paths @> ARRAY['/dashboard/templates'] OR allowed_paths @> ARRAY['/dashboard/finance'] OR allowed_paths @> ARRAY['/dashboard/campaigns'])));
CREATE POLICY sponsor_offers_write ON public.sponsor_offers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'superadmin')) WITH CHECK(public.has_role(auth.uid(),'superadmin'));
ALTER TABLE public.campaigns ADD COLUMN sponsor_offer_id uuid REFERENCES public.sponsor_offers(id);
CREATE TABLE public.finance_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.sponsor_accounts(id), campaign_id uuid REFERENCES public.campaigns(id), offer_id uuid REFERENCES public.sponsor_offers(id), external_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('revenue','expense')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','paid','rejected')), amount_cents bigint NOT NULL CHECK(amount_cents>=0 AND amount_cents<=100000000000), currency text NOT NULL DEFAULT 'EUR' CHECK(currency IN ('EUR','USD','GBP')), category text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', occurred_on date NOT NULL, due_on date, source text NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','import','api')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,external_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_entries TO authenticated; GRANT ALL ON public.finance_entries TO service_role;
ALTER TABLE public.finance_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_entries_read ON public.finance_entries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths @> ARRAY['/dashboard/finance']));
CREATE POLICY finance_entries_write ON public.finance_entries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'superadmin')) WITH CHECK(public.has_role(auth.uid(),'superadmin'));
CREATE INDEX finance_entries_period ON public.finance_entries(currency,occurred_on,account_id,campaign_id);
CREATE OR REPLACE FUNCTION public.validate_finance_attribution() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.offer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sponsor_offers WHERE id=NEW.offer_id AND account_id=NEW.account_id) THEN RAISE EXCEPTION 'Offer does not belong to account'; END IF; IF NEW.campaign_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.campaigns c JOIN public.sponsor_offers o ON o.id=c.sponsor_offer_id WHERE c.id=NEW.campaign_id AND o.account_id<>NEW.account_id) THEN RAISE EXCEPTION 'Campaign belongs to another sponsor account'; END IF; RETURN NEW; END $$;
CREATE TRIGGER finance_attribution BEFORE INSERT OR UPDATE ON public.finance_entries FOR EACH ROW EXECUTE FUNCTION public.validate_finance_attribution();
CREATE OR REPLACE FUNCTION public.finance_campaign_deliveries(_from date,_to date) RETURNS TABLE(campaign_id uuid,campaign_name text,delivered bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.name,count(DISTINCT e.message_id) FROM public.campaigns c LEFT JOIN public.delivery_events e ON e.campaign_id=c.id AND e.event_type='delivered' AND e.occurred_at>=_from::timestamptz AND e.occurred_at<(_to+1)::timestamptz WHERE public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.worker_tasks WHERE user_id=auth.uid() AND status='active' AND allowed_paths @> ARRAY['/dashboard/finance']) GROUP BY c.id,c.name $$;
REVOKE ALL ON FUNCTION public.finance_campaign_deliveries(date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finance_campaign_deliveries(date,date) TO authenticated,service_role;